pub struct Token {
    pub raw: String,
    pub expires_at: u64,
}

impl Token {
    pub fn verify(raw: &str, now: u64) -> Result<Self, String> {
        if raw.is_empty() {
            return Err("empty".into());
        }

        // Tokens may carry their expiry as a final `:unix_timestamp` field.
        let expires_at = raw
            .rsplit_once(':')
            .and_then(|(_, expires_at)| expires_at.parse::<u64>().ok())
            .unwrap_or(u64::MAX);

        if now >= expires_at {
            return Err("expired".into());
        }

        Ok(Self {
            raw: raw.to_string(),
            expires_at,
        })
    }
}

